f = open('17.txt').readline()
M = [int(i) for i in f]
max_19 = max(i for i in M if abs(i) % 100 == 19)

A = []
for i in range(len(M) - 1):
    if (len(str(abs(M[i]))) == 2) + (len(str(abs(M[i+1]))) == 2) == 1:
        if M[i] + M[i+1] > max_19:
            A.append(M[i] + M[i+1])
print(len(A), max(A))
